action_details.action_postfix:
// Economic nexus established per Wayfair - filing required
// FL threshold: $50,000 (lower than typical $100K)
// Apportionment will be calculated by tables 7000-7500

// No nexus - no filing required
0.0 apportionment.state_tax xdef
apportionment.state_payments apportionment.state_refund_or_owed xdef

// Calculate Florida state additions
0.0 /additions xdef

// FL addition: Interest on U.S. government obligations
// (Exempt from federal tax but taxable to FL)
// revenue.federal_bond_interest additions add /additions xdef

// FL addition: State income tax refunds included in federal income
// (FL has no state income tax for individuals, but this can apply to corps)
// revenue.state_tax_refund additions add /additions xdef

// FL addition: IRC § 78 gross-up for foreign tax credit
// revenue.section_78_gross_up additions add /additions xdef

additions apportionment.state_additions xdef

// Calculate Florida state subtractions
0.0 /subtractions xdef

// FL subtraction: Municipal bond interest from other states
// (Taxable federally but exempt from FL tax for FL bonds)
// revenue.other_state_municipal_interest subtractions add /subtractions xdef

// FL subtraction: Certain dividend income
// (FL allows subtraction for certain dividends under FL Statute § 220.13)
// revenue.qualified_dividends_fl_exempt subtractions add /subtractions xdef

// FL subtraction: State NOL deduction
// (FL has its own NOL rules separate from federal)
// result.fl_nol_deduction subtractions add /subtractions xdef

subtractions apportionment.state_subtractions xdef

// Florida uses 5.5% flat rate
apportionment.state_taxable_income apportionment.state_tax_rate mul
apportionment.state_tax xdef

// Subtract Florida state credits
apportionment.state_tax apportionment.state_credits sub
0.0 max apportionment.state_tax xdef

// Calculate refund or amount owed
apportionment.state_payments apportionment.state_tax sub
apportionment.state_refund_or_owed xdef
